-- Keep assigned and historical questions intact. Only availability changes.
do $retire$
begin
 if (select count(*) from game.questions where enabled and category='flags'
     and id ~ '^flag-territory-v1-.*-(region|affiliation|feature)$')<>78 then
  raise exception 'Expected 78 active territory knowledge questions';
 end if;
end
$retire$;

update game.questions
set enabled=false
where enabled and category='flags' and id ~ '^flag-territory-v1-.*-(region|affiliation|feature)$';

alter table game.questions add constraint active_flags_require_flag_identification
check (
 not enabled or category <> 'flags' or coalesce(
  (media->>'type'='image'
   and (media->>'src' like '/media/flags/%' or media->>'src' like '/flags/territories/%')
   and prompt in ('Zu welchem Land gehört diese Flagge?','Zu welchem Land oder Gebiet gehört diese Flagge?'))
  or (media->>'type'='flag-options' and media->>'src'='choice:flags'
   and (prompt like 'Welche dieser vier Flaggen gehört zu %' or prompt like 'Welche dieser Flaggen steht für %')
   and jsonb_array_length(provenance->'optionImages')=4),
 false)
);

-- Use the same systematic 8% sampling as solo play. A per-room phase spreads
-- the allowance over short rounds and leaves the default world picker intact.
do $picker$
declare
 definition text:=pg_get_functiondef('game.pick_balanced_question(text,integer,uuid,text[])'::regprocedure);
 declaration text:='oldest numeric; chosen text;';
 pool_start text:=' with recent as (';
 pool_filter text:='where q.enabled and q.category=p_category and not(q.id=any(p_excluded)) and not exists(';
 topic_branch text:=$snippet$ if p_category='world' then$snippet$;
begin
 if strpos(definition,declaration)=0 or strpos(definition,pool_start)=0
    or strpos(definition,pool_filter)=0 or strpos(definition,topic_branch)=0 then
  raise exception 'Unexpected world question picker definition';
 end if;
 definition:=replace(definition,declaration,declaration||
  ' territory_slot boolean:=false; world_position integer; territory_phase integer;');
 definition:=replace(definition,pool_start,$snippet$
 if p_category='world' then
  if p_room is null then
   territory_slot:=random()<0.08;
  else
   select count(*) into world_position
   from game.match_questions mq join game.questions q on q.id=mq.question_id
   where mq.room_id=p_room and q.category='world';
   territory_phase:=((pg_catalog.hashtextextended(p_room::text,0)%100+100)%100)::integer;
   territory_slot:=((world_position+1)*8+territory_phase)/100>(world_position*8+territory_phase)/100;
  end if;
 end if;
 with recent as ($snippet$);
 definition:=replace(definition,pool_filter,$snippet$where q.enabled and q.category=p_category and not(q.id=any(p_excluded))
  and (p_category<>'world' or coalesce(q.provenance->>'topic'='Regionen & Gebiete',false)=territory_slot)
  and (not territory_slot or not exists(
   select 1 from game.match_questions mq join game.questions previous on previous.id=mq.question_id
   where mq.room_id=p_room
    and previous.provenance->>'territoryQuestionType'=q.provenance->>'territoryQuestionType'
  ))
  and not exists($snippet$);
 -- Only the original topic-selection branch is replaced. The inserted phase
 -- calculation is added in the same pass with a distinct condition.
 definition:=replace(definition,$snippet$ if p_category='world' then
  select jsonb_object_agg(t,$snippet$,$snippet$ if p_category='world' and not territory_slot then
  select jsonb_object_agg(t,$snippet$);
 execute definition;
end
$picker$;

